    pending_cards=(SELECT COUNT(*) FROM turn_cards c INDEXED BY idx_turn_cards_session_pending WHERE c.project_id=learning_sessions.project_id AND c.session_id=learning_sessions.session_id AND c.state='pending'),
    due_cards=(SELECT COUNT(*) FROM turn_cards c INDEXED BY idx_turn_cards_uncovered WHERE c.project_id=learning_sessions.project_id AND c.session_id=learning_sessions.session_id AND c.state='carded' AND c.covered=0),
    signal_cards=(SELECT COUNT(*) FROM turn_cards c  WHERE c.project_id=learning_sessions.project_id AND c.session_id=learning_sessions.session_id AND c.state='carded' AND IFNULL(c.signal,'none')<>'none'),
    last_carded_at=(SELECT MAX(c.carded_at) FROM turn_cards c WHERE c.project_id=learning_sessions.project_id AND c.session_id=learning_sessions.session_id AND c.state='carded'),
    next_model_due_at=(SELECT MIN(c.due_at) FROM turn_cards c WHERE c.project_id=learning_sessions.project_id AND c.session_id=learning_sessions.session_id AND c.state='pending' AND c.due_at IS NOT NULL),
